package in.gov.nic.apar.config;

import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component;
@Component public class DemoSeed implements ApplicationRunner { private final JdbcTemplate db; private final PasswordEncoder enc; @Value("${apar.demo-seed:false}") boolean enabled; public DemoSeed(JdbcTemplate d,PasswordEncoder e){db=d;enc=e;} public void run(ApplicationArguments a){if(!enabled)return; Integer n=db.queryForObject("select count(*) from tran.user_account",Integer.class);if(n!=null&&n>0)return; long dept=db.queryForObject("select id from tran.department where code='IT'",Long.class); long auth=db.queryForObject("insert into tran.user_account(email,password_hash,role,enabled) values('authority@nic.in',?,'AUTHORITY',true) returning id",Long.class,enc.encode("Demo@12345")); String[][] people={{"EMP001","Ananya","Sharma","employee@nic.in"},{"EMP002","Priya","Das","priya@nic.in"},{"EMP003","Sunil","Deb","sunil@nic.in"},{"EMP004","Rebecca","Paul","rebecca@nic.in"}}; for(String[] p:people){long id=db.queryForObject("insert into tran.employee_details(employee_code,first_name,last_name,department_id,designation,email,active) values(?,?,?,?,'Officer',?,true) returning id",Long.class,p[0],p[1],p[2],dept,p[3]);db.update("insert into tran.user_account(employee_id,email,password_hash,role,enabled) values(?,?,?,'EMPLOYEE',true)",id,p[3],enc.encode("Demo@12345"));} db.update("insert into tran.acr_cycle(assessment_year,due_date,is_open) values('2026-2027',current_date+30,true)"); } }
